ALTER POLICY "Read listing photos" ON storage.objects TO authenticated USING (bucket_id='reloop-photos' AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.reloop_records l JOIN public.reloop_records r ON r.kind='interests' AND r.data->>'listingId'=l.data->>'id' AND coalesce(r.data->>'targetKind','listings')='listings' WHERE l.kind='listings' AND l.data->'photos' ? name AND r.owner_id=auth.uid() AND r.data->>'status' IN ('accepted','handover','completed'))));